    else if (t[i] === 'S') { list.push(new Square(t[i + 1])); i += 2; }
    else { list.push(new Triangle(t[i + 1], t[i + 2])); i += 3; }
  }
  return list.reduce((sum, s) => sum + s.area(), 0);
}

