        return 0
class Rect(Shape):
    def __init__(self, w, h):
        self.w, self.h = w, h
    def area(self):
        return self.w * self.h
class Square(Shape):
    def __init__(self, s):
        self.s = s
    def area(self):
        return self.s * self.s
class Triangle(Shape):
    def __init__(self, b, h):
        self.b, self.h = b, h
    def area(self):
        return (self.b * self.h) // 2

def solve(shapes):
    t = shapes.split()
    out, i = [], 0
    while i < len(t):
        if t[i] == 'R':
            out.append(Rect(int(t[i + 1]), int(t[i + 2]))); i += 3
        elif t[i] == 'S':
            out.append(Square(int(t[i + 1]))); i += 2
        else:
            out.append(Triangle(int(t[i + 1]), int(t[i + 2]))); i += 3
    return sum(s.area() for s in out)

