class Counter:
    def __init__(self):
        self.value = 0
        self.done = []
        self.undone = []
    def add(self, x):
        self.value += x
        self.done.append(x)
        self.undone = []
    def undo(self):
        if self.done:
            x = self.done.pop()
            self.value -= x
            self.undone.append(x)
    def redo(self):
        if self.undone:
            x = self.undone.pop()
            self.value += x
            self.done.append(x)

def solve(commands):
    t = commands.split()
    c = Counter()
    i = 0
    while i < len(t):
        if t[i] == 'add':
            i += 1
            c.add(int(t[i]))
        elif t[i] == 'undo':
            c.undo()
        elif t[i] == 'redo':
            c.redo()
        i += 1
    return c.value

