  const students = records.split(';').map((r) => r.trim().split(/\s+/)).map((p) => new Student(p[0], p.slice(1).map(Number)));
  students.sort((a, b) => b.average() - a.average() || (a.name < b.name ? -1 : 1));
  return students[0].name;
}

