class Student:
    def __init__(self, name, marks):
        self.name, self.marks = name, marks
    def average(self):
        return sum(self.marks) / len(self.marks)

def solve(records):
    students = []
    for r in records.split(';'):
        p = r.split()
        students.append(Student(p[0], [int(x) for x in p[1:]]))
    students.sort(key=lambda s: (-s.average(), s.name))
    return students[0].name

